		if (!Parent.hInsertAfter) Parent.hInsertAfter = TVI_FIRST;
		Parent.DUMMYUNIONNAME.item.hItem = NULL;
		Parent.DUMMYUNIONNAME.item.mask = TVIF_PARAM|TVIF_CHILDREN|TVIF_IMAGE|TVIF_SELECTEDIMAGE|TVIF_TEXT;
